INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Botnetz?', 2, '[{"text": "Netzwerk infizierter Geräte", "correct": true, "because": "Fernsteuerung durch Angreifer"}, {"text": "Sicheres lokales Netzwerk", "correct": false, "because": "Kein Sicherheitsfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt ein Botnetz?', 3, '[{"text": "Böswillige Aktivitäten durchführen", "correct": true, "because": "z.B. DDoS-Angriffe"}, {"text": "Netzwerkleistung verbessern", "correct": false, "because": "Kein positiver Zweck"}, {"text": "Daten sichern", "correct": false, "because": "Kein Schutzfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aktivitäten können Botnetze ausführen?', 5, '[{"text": "DDoS-Angriffe", "correct": true, "because": "Server überlasten"}, {"text": "Spam-Versand", "correct": true, "because": "Massenmails"}, {"text": "Datendiebstahl", "correct": true, "because": "Sensible Daten stehlen"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Botnetz besteht aus kompromittierten Geräten. b) Es wird immer vom Nutzer bemerkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft unbemerkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Botnetz?', 4, '[{"text": "Infektion durch Malware", "correct": false, "because": "Grundlage"}, {"text": "Command-and-Control-Server", "correct": false, "because": "Steuerung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Botnetz einen Command-and-Control-Server nutzt?', 2, '[{"text": "Ja", "correct": true, "because": "C&C für Steuerung"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird oft zur Steuerung eines Botnetzes verwendet?', 3, '[{"text": "C&C-Server", "correct": true, "because": "Command-and-Control"}, {"text": "E-Mail", "correct": false, "because": "Infektion, nicht Steuerung"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Erstellung eines Botnetzes?', 5, '[{"text": "Malware-Infektion", "correct": true, "because": "Geräte kompromittieren"}, {"text": "C&C-Infrastruktur", "correct": true, "because": "Steuerung einrichten"}, {"text": "Marketing", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Botnetze führen DDoS-Angriffe durch. b) Sie sind immer legal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Illegal genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Botnetz unwichtig?', 4, '[{"text": "Malware", "correct": false, "because": "Infektion"}, {"text": "Netzwerksteuerung", "correct": false, "because": "C&C"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Botnetz groß sein, um effektiv zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine wirksam"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Botnetz für Angreifer?', 4, '[{"text": "Skalierbarkeit", "correct": true, "because": "Viele Geräte"}, {"text": "Verdeckte Operationen", "correct": true, "because": "Unbemerkt"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Botnetze nur für DDoS genutzt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Spam, Datendiebstahl"}, {"text": "Ja", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Schutz vor Botnetzen?', 3, '[{"text": "Malware-Schutz", "correct": true, "because": "Infektion verhindern"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Botnetze nutzen Malware. b) Sie sind immer sichtbar für Nutzer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft unsichtbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Botnetz für Nutzer?', 5, '[{"text": "Leistungsverlust", "correct": true, "because": "Ressourcen genutzt"}, {"text": "Datenverlust", "correct": true, "because": "Diebstahl möglich"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Botnetzen?', 3, '[{"text": "Erkennung und Abwehr", "correct": true, "because": "Sicherheitsmaßnahmen"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Botnetz IoT-Geräte umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. Kameras"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Botnetz erkennen?', 4, '[{"text": "Wireshark", "correct": true, "because": "Netzwerkanalyse"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
